#include <string>
#include <algorithm>

class Player {
private:
    std::string name_;
    int health_;
public:
    Player(const std::string& name, int health = 100)
        : name_(name), health_(health) {}

    int get_health() const { return health_; }

    void take_damage(int damage) {
        health_ = std::max(0, health_ - damage);
    }
};

