lessons.solution_code:
#include <string>

class BankAccount {
private:
    std::string owner_;
    double balance_;
public:
    BankAccount(const std::string& owner, double initial_balance = 0.0)
        : owner_(owner), balance_(initial_balance) {}

    double get_balance() const { return balance_; }

    void deposit(double amount) {
        if (amount > 0) balance_ += amount;
    }

    bool withdraw(double amount) {
        if (balance_ >= amount) {
            balance_ -= amount;
            return true;
        }
        return false;
    }
};

